package mz.co.aprendaacodar.blog.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.common.enums.Enums.BlogPostStatus;import mz.co.aprendaacodar.user.entity.User;import java.time.Instant;
@Entity @Table(name="blog_posts") public class BlogPost extends BaseEntity {@Column(nullable=false,length=180) private String title;@Column(nullable=false,unique=true,length=200) private String slug;@Column(nullable=false,length=500) private String excerpt;@Column(nullable=false,columnDefinition="TEXT") private String content;private String coverImageKey;@ManyToOne(optional=false,fetch=FetchType.LAZY) private User author;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private BlogPostStatus status=BlogPostStatus.DRAFT;private Instant publishedAt;protected BlogPost(){}public BlogPost(String t,String e,String c,String image,User a){title=t;slug=slug(t);excerpt=e;content=c;coverImageKey=image;author=a;}private String slug(String x){return java.text.Normalizer.normalize(x,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("^-|-$","");}public void update(String t,String e,String c,String image){title=t;excerpt=e;content=c;coverImageKey=image;}public void publish(){status=BlogPostStatus.PUBLISHED;publishedAt=Instant.now();}public void archive(){status=BlogPostStatus.ARCHIVED;}public String getTitle(){return title;}public String getSlug(){return slug;}public String getExcerpt(){return excerpt;}public String getContent(){return content;}public String getCoverImageKey(){return coverImageKey;}public User getAuthor(){return author;}public BlogPostStatus getStatus(){return status;}public Instant getPublishedAt(){return publishedAt;}}
